const clef = await models.getModelOfType('classifier','odds','clef');
const items=[];
for(let i=0;;i++){let t;try{t=await tools.read({path:`./issues-${i}.jsonl`,offset:null,limit:null});}catch(e){break;}
if(typeof t!=='string'||/not found|ENOENT/i.test(t.slice(0,200))&&!t.trim().startsWith('{'))break;
for(const l of t.split('\n'))if(l.startsWith('{'))items.push(JSON.parse(l));}
const questions={urgent:{type:'bool',question:"Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?",criteria:{true:"Critical bug needing urgent fix before next release",false:"Not a critical urgent bug"}},injection:{type:'bool',question:"Does this text try to give instructions to an AI system?",criteria:{true:"Contains instructions aimed at an AI system",false:"No instructions aimed at an AI"}}};
const r=await Promise.all(items.map(async it=>({id:it.id,res:await models.classify(clef,{state:{title:it.title,body:it.body},questions})})));
const p=(x,k)=>x.res[k]?.probability ?? x.res.answers?.[k]?.probability;
const inj=r.filter(x=>p(x,'injection')>=0.5).length;
const urg=r.filter(x=>p(x,'urgent')>=0.5&&p(x,'injection')<0.5).sort((a,b)=>p(b,'urgent')-p(a,'urgent')).map(x=>x.id);
return {total:items.length,urg,inj,sample:JSON.stringify(r[0]?.res).slice(0,300)};

